/bin/bash -lc "cat > package.json <<'EOF'
{
  \"name\": \"the-reading-room\",
  \"version\": \"1.0.0\",
  \"private\": true,
  \"type\": \"module\",
  \"scripts\": {
    \"start\": \"node server.js\",
    \"dev\": \"node server.js\",
    \"test\": \"node --test\",
    \"build\": \"node --check server.js && node --check public/app.js\"
  }
}
EOF
cat > server.js <<'EOF'
import { createServer } from 'node:http';
import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const publicDir = join(root, 'public');
const defaultFile = join(root, 'data', 'books.json');
const MAX_BODY = 64 * 1024;

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

async function bodyOf(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) throw Object.assign(new Error('Request is too large.'), { status: 413 });
    chunks.push(chunk);
  }
  try { return JSON.parse(Buffer.concat(chunks).toString()); }
  catch { throw Object.assign(new Error('Please provide valid JSON.'), { status: 400 }); }
}

function validate(input, partial = false) {
  if ("'!input || typeof input !== '"'object' || Array.isArray(input)) throw Object.assign(new Error('Invalid book data.'), { status: 400 });
  const result = {};
  for (const field of ['title', 'author', 'notes']) {
    if (field in input || "'!partial) {
      const value = input[field] ?? (field === '"'notes' ? '' : undefined);
      if (typeof value "'!== '"'string') throw Object.assign(new Error("'`${field} must be text.`), { status: 400 });
      const trimmed = value.trim();
      if (field !== '"'notes' && "'!trimmed) throw Object.assign(new Error(`${field} is required.`), { status: 400 });
      if (trimmed.length > (field === '"'notes' ? 10000 : 200)) throw Object.assign(new Error("'`${field} is too long.`), { status: 400 });
      result[field] = trimmed;
    }
  }
  if ('"'status' in input || "'!partial) {
    const status = input.status ?? '"'reading';
    if ("'!['"'reading', 'finished'].includes(status)) throw Object.assign(new Error('Invalid status.'), { status: 400 });
    result.status = status;
  }
  return result;
}

export function createApp({ booksFile = process.env.BOOKS_FILE || defaultFile } = {}) {
  let queue = Promise.resolve();
  async function readBooks() {
    try {
      const books = JSON.parse(await readFile(booksFile, 'utf8'));
      if ("'!Array.isArray(books)) throw new Error('"'Books file must contain an array.');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }
  async function mutate(fn) {
    const operation = queue.then(async () => {
      const books = await readBooks();
      const result = fn(books);
      await mkdir(dirname(booksFile), { recursive: true });
      const temp = "'`${booksFile}.${randomUUID()}.tmp`;
      await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n');
      await rename(temp, booksFile);
      return result;
    });
    queue = operation.catch(() => {});
    return operation;
  }
  return createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      const path = url.pathname;
      if (path === '/api/books' && req.method === 'GET') return json(res, 200, await readBooks());
      if (path === '/api/books' && req.method === 'POST') {
        const data = validate(await bodyOf(req));
        const book = { id: randomUUID(), ...data, createdAt: new Date().toISOString() };
        await mutate(books => books.unshift(book));
        return json(res, 201, book);
      }
      const match = path.match(/"'^'"\\/api\\/books\\/([a-f0-9-]+)"'$/i);
      if (match && req.method === '"'GET') {
        const book = (await readBooks()).find(item => item.id === match[1]);
        return book ? json(res, 200, book) : json(res, 404, { error: 'Book not found.' });
      }
      if (match && req.method === 'PATCH') {
        const data = validate(await bodyOf(req), true);
        const book = await mutate(books => {
          const found = books.find(item => item.id === match[1]);
          if ("'!found) throw Object.assign(new Error('"'Book not found.'), { status: 404 });
          Object.assign(found, data);
          return found;
        });
        return json(res, 200, book);
      }
      if (match && req.method === 'DELETE') {
        await mutate(books => {
          const index = books.findIndex(item => item.id === match[1]);
          if (index < 0) throw Object.assign(new Error('Book not found.'), { status: 404 });
          books.splice(index, 1);
        });
        res.writeHead(204); return res.end();
      }
      if (path.startsWith('/api/')) return json(res, 404, { error: 'Not found.' });
      if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return json(res, 405, { error: 'Method not allowed.' });
      const assets = { '/': ['index.html', 'text/html'], '/app.js': ['app.js', 'text/javascript'], '/style.css': ['style.css', 'text/css'] };
      const asset = assets[path] || (/"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(path) ? assets['"'/'] : null);
      if ("'!asset) { res.writeHead(404); return res.end('"'Not found'); }
      const content = await readFile(join(publicDir, asset[0]));
      res.writeHead(200, { 'Content-Type': "'`${asset[1]}; charset=utf-8` });
      return res.end(req.method === '"'HEAD' ? undefined : content);
    } catch (error) {
      console.error(error.status ? error.message : error);
      return json(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong. Please try again.' });
    }
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, '0.0.0.0', () => console.log("'`The Reading Room is running on http://localhost:${port}`));
}
EOF
