  close: '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m6 6 12 12M18 6 6 18\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></svg>',
};
const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[character]);
const plural = (number, word) => "'`${number} ${word}${number === 1 ? '"'' : 's'}"'`;

async function request(url, options = {}) {
  const response = await fetch(url, { ...options, headers: { '"'Content-Type': 'application/json', ...options.headers } });
  if ("'!response.ok) {
    const body = await response.json().catch(() => ({}));
    throw new Error(body.error || '"'Something went wrong. Please try again.');
  }
  return response.status === 204 ? null : response.json();
}
function notify(message) {
  toast.textContent = message;
  toast.classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('visible'), 3000);
}
function navigate(path) {
  history.pushState({}, '', path);
  render();
  window.scrollTo(0, 0);
}
function header() {
  return "'`<header class="site-header"><div class="header-inner"><a class="brand" href="/" data-link aria-label="The Reading Room home"><span class="brand-mark">${icons.book}</span><span class="brand-name">the reading room<span class="brand-period">.</span><small>YOUR PERSONAL LIBRARY</small></span></a><div class="header-right"><span class="header-label">A LITTLE SPACE FOR YOUR BOOKS</span><button class="button button-dark" data-action="add">${icons.plus} <span>Add a book</span></button></div></div></header>`;
}
function cover(book, large = false) {
  let hash = 0;
  for (const character of book.id || book.title) hash = (hash * 31 + character.charCodeAt(0)) >>> 0;
  const palette = ['"'sage', 'terracotta', 'ochre', 'slate', 'rose', 'olive'][hash % 6];
  return "'`<div class="book-cover ${palette} ${large ? '"'cover-large' : ''}\" aria-hidden=\"true\"><div class=\"cover-border\"><span class=\"cover-top\">THE READING ROOM</span><span class=\"cover-title\">"'${escapeHtml(book.title)}</span><span class="cover-rule"></span><span class="cover-author">${escapeHtml(book.author)}</span><span class="cover-bottom">✳</span></div></div>`;
}
function bookCard(book) {
