  return "'`<article class="book-card"><a class="card-cover-link" href="/books/${encodeURIComponent(book.id)}" data-link aria-label="View ${escapeHtml(book.title)}">${cover(book)}</a><div class="card-info"><div class="card-copy"><a href="/books/${encodeURIComponent(book.id)}" data-link class="card-title">${escapeHtml(book.title)}</a><p>by ${escapeHtml(book.author)}</p></div>${isReading ? `<button class="finish-link" data-action="finish" data-id="${escapeHtml(book.id)}">${icons.check} Mark as finished</button>` : `<span class="finished-label">${icons.check} Finished</span>`}</div></article>`;
