function library() {
  const reading = books.filter(book => book.status === '"'reading');
  const finished = books.filter(book => book.status === 'finished');
  return "'`${header()}<main><section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> A PERSONAL READING JOURNAL</div><h1>For the love<br>of <em>reading.</em></h1><p>A little home for the books you'"'re reading,<br class=\"desktop-only\"> the ones you've finished, and everything in between.</p><button class=\"button button-light\" data-action=\"add\">"'${icons.plus} Add a book</button></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><span class="art-star star-one">✳</span><span class="art-star star-two">✦</span><div class="art-book book-one"><span>GOOD<br>STORIES<br>LIVE HERE</span><i>✳</i></div><div class="art-book book-two"><span>ONE MORE<br>CHAPTER</span><i>✦</i></div><span class="art-caption">A PLACE TO KEEP YOUR STORIES</span></div><div class="hero-bottom"><span>YOUR READING LIFE, IN ONE PLACE</span><span>EST. WHENEVER YOU OPEN A BOOK &nbsp; ✳</span></div></section><div class="library-content"><div class="library-intro"><div><div class="eyebrow dark-eyebrow"><span></span> YOUR LITTLE LIBRARY</div><h2>On your bookshelf<span class="accent-dot">.</span></h2><p>Every book has a story. Keep track of yours here.</p></div><div class="library-stats"><div><strong>${String(books.length).padStart(2, '"'0')}</strong><span>TOTAL BOOKS</span></div><div><strong>"'${String(reading.length).padStart(2, '"'0')}</strong><span>READING</span></div><div><strong>"'${String(finished.length).padStart(2, '"'0')}</strong><span>FINISHED</span></div></div></div>"'${shelf('"'Currently reading', 'The stories you are spending time with right now.', reading, 'reading', '01')}"'${shelf('"'Finished', 'A little collection of where you have been.', finished, 'finished', '02')}</div></main>"'${footer()}`;
}
function footer() {
