}
function detail(book) {
  const reading = book.status === '"'reading';
  return "'`${header()}<main class="detail-main"><a href="/" data-link class="back-link">${icons.back} Back to your bookshelf</a><div class="detail-layout"><div class="detail-cover-wrap">${cover(book, true)}<span class="cover-caption">A STORY FROM YOUR SHELF &nbsp; ✳</span></div><div class="detail-content"><div class="eyebrow dark-eyebrow"><span></span> ${reading ? '"'CURRENTLY READING' : 'FINISHED'}</div><h1>"'${escapeHtml(book.title)}<span class="accent-dot">.</span></h1><p class="detail-author">by ${escapeHtml(book.author)}</p><div class="detail-actions"><button class="button button-dark" data-action="toggle-status" data-id="${escapeHtml(book.id)}">${icons.check} ${reading ? '"'Mark as finished' : 'Mark as reading'}</button><button class=\"button button-outline\" data-action=\"share\">"'${icons.share} Copy book link</button></div><div class="detail-divider"></div><div class="notes-heading"><div><div class="section-kicker"><span>✳</span> A LITTLE SOMETHING TO REMEMBER</div><h2>Your notes</h2></div><button class="text-button" data-action="edit" data-id="${escapeHtml(book.id)}">Edit book <span>↗</span></button></div><p class="notes-text ${book.notes ? '"'' : 'notes-empty'}\">"'${book.notes ? escapeHtml(book.notes) : '"'No notes yet. Add a thought, a favorite line, or anything you want to remember.'}</p><button class=\"delete-button\" data-action=\"delete\" data-id=\""'${escapeHtml(book.id)}">Remove book</button></div></div></main>${footer()}`;
