function notFound() {
  return `${header()}<main class="not-found"><div class="eyebrow dark-eyebrow"><span></span> LOST YOUR PAGE?</div><h1>Book not found<span class="accent-dot">.</span></h1><p>We couldn'"'t find this book on the shelf.</p><a href=\"/\" data-link class=\"button button-dark\">"'${icons.back} Back to your bookshelf</a></main>${footer()}`;
}
function render() {
  const match = location.pathname.match(/''^'"\\/books\\/(["'^/]+)'"\\/?"'$/);
