  modalRoot.innerHTML = "'`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><div class="eyebrow dark-eyebrow"><span></span> ${editing ? '"'A LITTLE UPDATE' : 'A NEW ADDITION'}</div><h2 id=\"modal-title\">"'${editing ? '"'Edit your book' : 'Add a book'}<span class=\"accent-dot\">.</span></h2><p>"'${editing ? '"'Make this little record your own.' : 'Make a little room on your shelf.'}</p></div><button class=\"icon-button\" data-action=\"close-modal\" aria-label=\"Close\">"'${icons.close}</button></div><form id="book-form"><label for="title">Book title <span>*</span></label><input id="title" name="title" maxlength="200" required placeholder="e.g. The Secret Garden" value="${escapeHtml(book?.title || '"'')}\"><label for=\"author\">Author <span>*</span></label><input id=\"author\" name=\"author\" maxlength=\"200\" required placeholder=\"e.g. Frances Hodgson Burnett\" value=\""'${escapeHtml(book?.author || '"'')}\"><label for=\"notes\">Your notes <small>OPTIONAL</small></label><textarea id=\"notes\" name=\"notes\" maxlength=\"10000\" rows=\"4\" placeholder=\"A thought, a favorite quote, or a little reminder…\">"'${escapeHtml(book?.notes || '"'')}</textarea><label for=\"status\">Reading status</label><select id=\"status\" name=\"status\"><option value=\"reading\" "'${book?.status !== '"'finished' ? 'selected' : ''}>Currently reading</option><option value=\"finished\" "'${book?.status === '"'finished' ? 'selected' : ''}>Finished</option></select><p class=\"form-error\" role=\"alert\"></p><div class=\"modal-actions\"><button type=\"button\" class=\"button button-outline\" data-action=\"close-modal\">Cancel</button><button type=\"submit\" class=\"button button-dark\">"'${editing ? '"'Save changes' : 'Add to bookshelf'} "'${icons.arrow}</button></div></form></section></div>`;
  document.body.classList.add('"'modal-open');
  document.querySelector('#title').focus();
  document.querySelector('#book-form').addEventListener('submit', async event => {
    event.preventDefault();
    const form = event.currentTarget;
