    }
  }
  if (action === 'delete' && confirm('Remove this book from your bookshelf?')) {
    try { await request("'`/api/books/${id}`, { method: '"'DELETE' }); books = books.filter(book => book.id "'!== id); navigate('"'/'); notify('Book removed from your bookshelf.'); }
    catch (error) { notify(error.message); }
  }
});
document.addEventListener('keydown', event => { if (event.key === 'Escape' && modalRoot.firstChild) closeModal(); });
window.addEventListener('popstate', render);
try { books = await request('/api/books'); render(); }
catch (error) { app.innerHTML = "'`${header()}<main class="not-found"><h1>Couldn'"'t open your library<span class=\"accent-dot\">.</span></h1><p>"'${escapeHtml(error.message)}</p><button class="button button-dark" onclick="location.reload()">Try again</button></main>${footer()}`; }
