/bin/bash -lc "cat > test/app.test.js <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from '../server.js';

async function start(booksFile) {
  const server = createApp({ booksFile });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return { server, url: "'`http://127.0.0.1:${server.address().port}` };
}
const stop = server => new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));

test('"'books persist, have shareable pages, and can be updated', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'reading-room-'));
  const booksFile = join(directory, 'books.json');
  let running = await start(booksFile);
  try {
    const initial = await fetch("'`${running.url}/api/books`).then(response => response.json());
    assert.deepEqual(initial, []);
    const invalid = await fetch(`${running.url}/api/books`, { method: '"'POST', body: JSON.stringify({ title: ' ', author: 'Someone' }) });
    assert.equal(invalid.status, 400);
    const created = await fetch("'`${running.url}/api/books`, { method: '"'POST', body: JSON.stringify({ title: '  A Book  ', author: 'An Author', notes: 'A favorite passage' }) });
    assert.equal(created.status, 201);
    const book = await created.json();
    assert.equal(book.title, 'A Book');
    assert.equal(book.status, 'reading');
    const page = await fetch("'`${running.url}/books/${book.id}`);
    assert.equal(page.status, 200);
    assert.match(await page.text(), /The Reading Room/);
    const updated = await fetch(`${running.url}/api/books/${book.id}`, { method: '"'PATCH', body: JSON.stringify({ status: 'finished', notes: 'A new thought' }) }).then(response => response.json());
    assert.equal(updated.status, 'finished');
    assert.equal(updated.notes, 'A new thought');
    await stop(running.server);
    running = await start(booksFile);
    const afterRestart = await fetch("'`${running.url}/api/books/${book.id}`).then(response => response.json());
    assert.deepEqual(afterRestart, updated);
    assert.equal(JSON.parse(await readFile(booksFile, '"'utf8'))[0].id, book.id);
    const deleted = await fetch("'`${running.url}/api/books/${book.id}`, { method: '"'DELETE' });
    assert.equal(deleted.status, 204);
    assert.equal((await fetch("'`${running.url}/api/books/${book.id}`)).status, 404);
  } finally {
    await stop(running.server);
    await rm(directory, { recursive: true, force: true });
  }
});

test('"'simultaneous additions are all saved', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'reading-room-'));
  const running = await start(join(directory, 'books.json'));
  try {
    const responses = await Promise.all(Array.from({ length: 12 }, (_, index) => fetch("'`${running.url}/api/books`, { method: '"'POST', body: JSON.stringify({ title: "'`Book ${index}`, author: '"'An Author' }) })));
    assert.ok(responses.every(response => response.status === 201));
    const books = await fetch("'`${running.url}/api/books`).then(response => response.json());
    assert.equal(books.length, 12);
    assert.equal(new Set(books.map(book => book.id)).size, 12);
  } finally {
    await stop(running.server);
    await rm(directory, { recursive: true, force: true });
  }
});
EOF
npm test && npm run build'
